def fetch_raw(self) -> list[dict]:
    use_live = db.get_setting("use_live_scraping", "0") == "1"
    if use_live:
        try:
            return self.fetch_live() or []
        except NotImplementedError:
            return []   # this source has no live adapter yet; skip
        except Exception as e:  # never let one source break ingest
            print(f"  [{self.source_key}] live fetch failed ({e}); skipping")
            return []
    return self._load_fixtures()

def _get(self, url, rate_limit_sec=4.0):
    wait = rate_limit_sec - (time.time() - self._last_request)
    if wait > 0:
        time.sleep(wait)
    self._last_request = time.time()
    headers = {"User-Agent": "AkiyaScout/0.1 (personal research tool; contact rennesan@gmail.com)"}
    return httpx.get(url, headers=headers, timeout=20, follow_redirects=True)

