def derive_seismic(year):
    """Shin-Taishin (new seismic code) applies to buildings from 1981 onward."""
    if not year:
        return None
    return "shin_taishin" if year >= 1981 else "kyu_taishin"

def dedup_key(raw: dict) -> str:
    """Same prefecture + rounded area + rounded price = likely same house."""
    pref = (raw.get("prefecture_code") or "").lower()
    area = round((raw.get("building_area_sqm") or 0) / 5) * 5      # bucket to 5 sqm
    price = round((raw.get("price_jpy") or 0) / 100000) * 100000   # bucket to 100k yen
    addr = re.sub(r"[\s　0-9０-９-－]", "", (raw.get("address_ja") or ""))[:12]
    return hashlib.sha1(f"{pref}|{area}|{price}|{addr}".encode("utf-8")).hexdigest()

