GLOSSARY = {
    "空き家": "vacant house (akiya)", "古民家": "traditional kominka",
    "要リフォーム": "needs renovation", "温泉": "hot spring (onsen)",
    "雪国": "snow country", "駅徒歩": "walk from station",
    "即入居可": "move-in ready", "空き家バンク": "akiya bank", ...
}

def _stub_translate(text: str) -> str:
    out = text
    # longest keys first so compound terms win
    for ja in sorted(GLOSSARY, key=len, reverse=True):
        out = out.replace(ja, " " + GLOSSARY[ja] + " ")
    out = re.sub(r"\s+", " ", out).strip()
    out = out.replace("、", ", ").replace("。", ". ")
    return out.strip(" ,.")

