def jitter(lat, lng, seed):
    """Small deterministic offset (~+/-1.5km) so co-located pins separate."""
    if lat is None:
        return (None, None)
    return (lat + ((seed % 7) - 3) * 0.004, lng + (((seed // 7) % 7) - 3) * 0.004)

