def _cadence_trigger(cadence, custom_cron):
    if cadence == "daily":   return CronTrigger(hour=7, minute=0)
    if cadence == "weekly":  return CronTrigger(day_of_week="mon", hour=7, minute=0)
    if cadence == "monthly": return CronTrigger(day=1, hour=7, minute=0)
    if cadence == "custom" and custom_cron:
        return CronTrigger.from_crontab(custom_cron)
